INSERT INTO `oedict` (`word_id`, `letter`, `word`, `meaning`) VALUES
(350, 'a', '\nAdjunct', ' n. 1 (foll. By to, of) subordinate or incidental thing. 2 gram. Word or phrase used to explain or amplify the predicate, subject, etc. [latin: related to *adjoin]'),
