(2855, 'b', '\r\nBlood', 'relation  n. (also blood relative) relative by birth.'),
(2856, 'b', '\r\nBloodshed', ' n. Killing.'),
(2857, 'b', '\r\nBloodshot', ' adj. (of an eyeball) inflamed.'),
(2858, 'b', '\r\nBlood', 'sport  n. Sport involving the killing or wounding of animals.'),
