(2907, 'b', '\r\nBluebottle', ' n. Large buzzing fly; blowfly.'),
(2908, 'b', '\r\nBlue', 'cheese  n. Cheese with veins of blue mould.'),
(2909, 'b', '\r\nBlue-collar', ' attrib. Adj. (of a worker or work) manual; industrial.'),
(2910, 'b', '\r\nBlue-eyed', 'boy  n. Colloq. Favourite.'),
(2911, 'b', '\r\nBlue', 'funk  n. Colloq. Terror or panic.'),
