(9502, 'c', '\r\nCopier', ' n. Machine that copies (esp. Documents).'),
(9503, 'c', '\r\nCopilot', ' n. Second pilot in an aircraft.'),
(9504, 'c', '\r\nCoping', ' n. Top (usu. Sloping) course of masonry in a wall. [from *cope2]'),
(9505, 'c', '\r\nCoping', 'saw  n. D-shaped saw for cutting curves in wood. [from *cope1]'),
