(9525, 'c', '\r\nCopyist', ' n. Person who makes (esp. Written) copies.'),
(9526, 'c', '\r\nCopyright', ' â€”n. Exclusive legal right to print, publish, perform, film, or record material. â€”adj. Protected by copyright. â€”v. Secure copyright for (material).'),
(9527, 'c', '\r\nCopy-typist', ' n. Typist who types from documents rather than dictation.'),
(9528, 'c', '\r\nCopywriter', ' n. Person who writes or prepares advertising copy for publication.'),
(9529, 'c', '\r\nCoq', 'au vin  n. Casserole of chicken pieces in wine. [french]'),
(9530, 'c', '\r\nCoquette', ' n. Woman who flirts.  coquetry n. (pl. -ies). Coquettish adj. [french diminutive: related to *cock1]'),
(9531, 'c', '\r\nCor', ' int. Slang expressing surprise etc. [corruption of god]'),
(9532, 'c', '\r\nCor-', ' see *com-.'),
