(12334, 'd', '\r\nDutch', 'auction  n. One in which the price is progressively reduced.'),
(12335, 'd', '\r\nDutch', 'barn  n. Roof for hay etc., set on poles.'),
(12336, 'd', '\r\nDutch', 'cap  n. Dome-shaped contraceptive device fitting over the cervix.'),
(12337, 'd', '\r\nDutch', 'courage  n. Courage induced by alcohol.'),
(12338, 'd', '\r\nDutch', 'elm disease  n. Fungus disease of elms.'),
