(16364, 'f', '\r\nFree', 'trade  n. Trade without import restrictions etc.'),
(16365, 'f', '\r\nFree', 'vote  n. Parliamentary vote not subject to party discipline.'),
(16366, 'f', '\r\nFreeway', ' n. Us motorway.'),
(16367, 'f', '\r\nFree', 'wheel  n. Driving wheel of a bicycle, able to revolve with the pedals at rest.'),
