(17196, 'g', '\r\nGlutamate', ' n. Salt or ester of glutamic acid, esp. A sodium salt used to enhance the flavour of food.'),
(17197, 'g', '\r\nGlutamic', 'acid  n. Amino acid normally found in proteins. [from *gluten, *amine]'),
(17198, 'g', '\r\nGluten', ' n. Mixture of proteins present in cereal grains; sticky protein substance left when starch is washed out of flour. [latin gluten -tin- glue]'),
