(17728, 'g', '\r\nGuardroom', ' n. Room serving the same purpose as a guardhouse.'),
(17729, 'g', '\r\nGuardsman', ' n. Soldier belonging to a body of guards or regiment of guards.'),
(17730, 'g', '\r\nGuava', ' n. 1 edible pale orange fruit with pink flesh. 2 tree bearing this. [spanish]'),
(17731, 'g', '\r\nGubernatorial', ' adj. Esp. Us of or relating to a governor. [latin gubernator governor]'),
(17732, 'g', '\r\nGudgeon1', ' n. Small freshwater fish often used as bait. [french goujon from latin gobio *goby]'),
