(17888, 'h', '\r\nHadji', ' var. Of *hajji.'),
(17889, 'h', '\r\nHadn''t', ' contr. Had not.'),
(17890, 'h', '\r\nHaemal', ' adj. (us hem-) of the blood. [greek haima blood]'),
