(18238, 'h', '\r\nHave-not', ' n. (usu. In pl.) Colloq. Person lacking wealth or resources.'),
(18239, 'h', '\r\nHaven''t', ' contr. Have not.'),
(18240, 'h', '\r\nHaver', ' v. 1 vacillate, hesitate. 2 dial. Talk foolishly. [origin unknown]'),
