(18276, 'h', '\r\nHeartless', ' adj. Unfeeling, pitiless.  heartlessly adv.'),
(18277, 'h', '\r\nHeart-lung', 'machine  n. Machine that temporarily takes over the functions of the heart and lungs.'),
(18278, 'h', '\r\nHeart-rending', ' adj. Very distressing.'),
(18279, 'h', '\r\nHeart-searching', ' n. Examination of one''s own feelings and motives.'),
(18280, 'h', '\r\nHeartsick', ' adj. Despondent.'),
(18281, 'h', '\r\nHeartstrings', ' n.pl. One''s deepest feelings.'),
(18282, 'h', '\r\nHeartthrob', ' n. Colloq. Person for whom one has (esp. Immature) romantic feelings.'),
(18283, 'h', '\r\nHeart-to-heart', ' â€”attrib. Adj. (of a conversation etc.) Candid, intimate. â€”n. Candid or personal conversation.'),
(18284, 'h', '\r\nHeart-warming', ' adj. Emotionally rewarding or uplifting.'),
(18285, 'h', '\r\nHeartwood', ' n. Dense inner part of a tree-trunk, yielding the hardest timber.'),
(18286, 'h', '\r\nHearty', ' adj. (-ier, -iest) 1 strong, vigorous. 2 (of a meal or appetite) large. 3 warm, friendly.  heartiness n.'),
