(19194, 'h', '\r\nHenry', ' n. (pl. -s or -ies) electr. Si unit of inductance. [henry, name of a physicist]'),
(19195, 'h', '\r\nHep', ' var. Of *hip4.'),
(19196, 'h', '\r\nHepatic', ' adj. Of the liver. [greek hepar -atos liver]'),
(19197, 'h', '\r\nHepatitis', ' n. Inflammation of the liver. [related to *hepatic]'),
(19198, 'h', '\r\nHepta-', ' comb. Form seven. [greek]'),
