(19399, 'h', '\r\nHind2', ' n. Female (esp. Red) deer, esp. In and after the third year. [old english]'),
(19400, 'h', '\r\nHinder1', ' v. Impede; delay. [old english]'),
(19401, 'h', '\r\nHinder2', ' adj. Rear, hind (the hinder part). [old english]'),
(19402, 'h', '\r\nHindi', ' n. 1 group of spoken dialects of n. India. 2 literary form of hindustani, an official language of india. [urdu hind india]'),
(19403, 'h', '\r\nHindmost', ' adj. Furthest behind.'),
(19404, 'h', '\r\nHindquarters', ' n.pl. Hind legs and rump of a quadruped.'),
(19405, 'h', '\r\nHindrance', ' n. 1 hindering; being hindered. 2 thing that hinders.'),
(19406, 'h', '\r\nHindsight', ' n. Wisdom after the event.'),
