(19414, 'h', '\r\nHip1', ' n. Projection of the pelvis and the upper part of the thigh-bone. [old english]'),
(19415, 'h', '\r\nHip2', ' n. Fruit of a rose, esp. Wild. [old english]'),
(19416, 'h', '\r\nHip3', ' int. Introducing a united cheer (hip, hip, hooray). [origin unknown]'),
(19417, 'h', '\r\nHip4', ' adj. (also hep) (-pper, -ppest) slang trendy, stylish. [origin unknown]'),
(19418, 'h', '\r\nHip-bath', ' n. Portable bath in which one sits immersed to the hips.'),
