(21498, 'j', '\r\nJet', 'black  adj. & n. (as adj. Often hyphenated) deep glossy black.'),
(21499, 'j', '\r\nJet', 'engine  n. Engine using jet propulsion, esp. Of an aircraft.'),
(21500, 'j', '\r\nJet', 'lag  n. Exhaustion etc. Felt after a long flight across time zones.'),
(21501, 'j', '\r\nJet', 'plane  n. Plane with a jet engine.'),
