(21873, 'k', '\r\nKingdom', 'come  n. Colloq. The next world.'),
(21874, 'k', '\r\nKingfisher', ' n. Small bird with brightly coloured plumage, diving for fish etc.'),
(21875, 'k', '\r\nKing', 'of arms  n. A chief herald.'),
(21876, 'k', '\r\nKing', 'of beasts  n. Lion.'),
(21877, 'k', '\r\nKing', 'of birds  n. Eagle.'),
(21878, 'k', '\r\nKingpin', ' n. 1 main, large, or vertical bolt, esp. As a pivot. 2 essential person or thing.'),
(21879, 'k', '\r\nKing-post', ' n. Upright post from the tie-beam of a roof to the apex of a truss.'),
