(21883, 'k', '\r\nKing''s', 'guide  n. = *queen''s guide.'),
(21884, 'k', '\r\nKing''s', 'highway  n. = *queen''s highway.'),
(21885, 'k', '\r\nKing-size', ' adj. (also -sized) very large.'),
(21886, 'k', '\r\nKing''s', 'proctor  n. = *queen''s proctor.'),
(21887, 'k', '\r\nKing''s', 'scout  n. = *queen''s scout.'),
(21888, 'k', '\r\nKink', ' â€”n. 1 a twist or bend in wire etc. B tight wave in hair. 2 mental twist or quirk, esp. When perverse. â€”v. (cause to) form a kink. [low german or dutch]'),
(21889, 'k', '\r\nKinky', ' adj. (-ier, -iest) 1 colloq. A sexually perverted or unconventional. B (of clothing etc.) Bizarre and sexually provocative. 2 having kinks.  kinkily adv. Kinkiness n.'),
