(22772, 'l', '\r\nLimpet', 'mine  n. Delayed action mine attached to a ship''s hull.'),
(22773, 'l', '\r\nLimpid', ' adj. Clear, transparent.  limpidity n. [latin]'),
(22774, 'l', '\r\nLinage', ' n. 1 number of lines in printed or written matter. 2 payment by the line.'),
