(25072, 'm', '\r\nMotorman', ' n. Driver of an underground train, tram, etc.'),
(25073, 'm', '\r\nMotor', 'scooter  see *scooter.'),
(25074, 'm', '\r\nMotor', 'vehicle  n. Road vehicle powered by an internal-combustion engine.'),
(25075, 'm', '\r\nMotorway', ' n. Road for fast travel, with separate carriageways and limited access.'),
