(25195, 'm', '\r\nMulticultural', ' adj. Of several cultural groups.  multiculturalism n.'),
(25196, 'm', '\r\nMultidirectional', ' adj. Of, involving, or operating in several directions.'),
(25197, 'm', '\r\nMultifarious', ' adj. 1 many and various. 2 of great variety.  multifariousness n. [latin multifarius]'),
(25198, 'm', '\r\nMultiform', ' adj. 1 having many forms. 2 of many kinds.'),
(25199, 'm', '\r\nMultilateral', ' adj. 1 (of an agreement etc.) In which three or more parties participate. 2 having many sides.  multilaterally adv.'),
