(25918, 'n', '\r\nNorthern', ' adj. Of or in the north.  northernmost adj.  [old english]'),
(25919, 'n', '\r\nNortherner', ' n. Native or inhabitant of the north.'),
(25920, 'n', '\r\nNorthern', 'hemisphere  n. The half of the earth north of the equator.'),
(25921, 'n', '\r\nNorthern', 'lights  n.pl. Aurora borealis.'),
(25922, 'n', '\r\nNorthman', ' n. Native of scandinavia, esp. Norway. [old english]'),
(25923, 'n', '\r\nNorth-north-east', ' n. Point or direction midway between north and north-east.'),
