(26004, 'n', '\r\nNspcc', ' abbr. National society for the prevention of cruelty to children.'),
(26005, 'n', '\r\nNsw', ' abbr. New south wales.'),
(26006, 'n', '\r\nNt', ' abbr. 1 new testament. 2 northern territory (of australia). 3 national trust.'),
