(26732, 'o', '\r\nOutdated', ' adj. Out of date; obsolete.'),
(26733, 'o', '\r\nOutdistance', ' v. (-cing) leave (a competitor) behind completely.'),
(26734, 'o', '\r\nOutdo', ' v. (-doing; 3rd sing. Present -does; past -did; past part. -done) exceed, excel, surpass.'),
