(28763, 'p', '\r\nPop3', ' n. Esp. Us colloq. Father. [from *papa]'),
(28764, 'p', '\r\nPop.', ' Abbr. Population.'),
(28765, 'p', '\r\nPopadam', ' var. Of *poppadam.'),
