(32796, 's', '\r\nSelf-assured', ' n. Self-confident.  self-assurance n.'),
(32797, 's', '\r\nSelf-aware', ' adj. Conscious of one''s character, feelings, motives, etc.  self-awareness n.'),
(32798, 's', '\r\nSelf-catering', ' adj. (of a holiday, accommodation etc.) With cooking facilities provided, but no food.'),
(32799, 's', '\r\nSelf-censorship', ' n. Censoring of oneself.'),
