(32827, 's', '\r\nSelf-effacing', ' adj. Retiring; modest.  self-effacement n.'),
(32828, 's', '\r\nSelf-employed', ' adj. Working as a freelance or for one''s own business etc.  self-employment n.'),
(32829, 's', '\r\nSelf-esteem', ' n. Good opinion of oneself.'),
