(38112, 'u', '\r\nU-boat', ' n. Hist. German submarine. [german untersee undersea]'),
(38113, 'u', '\r\nU.c.', ' Abbr. Upper case.'),
(38114, 'u', '\r\nUcca', ' abbr. Universities central council on admissions.'),
(38115, 'u', '\r\nUda', ' abbr. Ulster defence association (a loyalist paramilitary organization).'),
(38116, 'u', '\r\nUdder', ' n. Baglike mammary organ of cattle etc., with several teats. [old english]'),
