(40018, 'w', '\r\nWater', 'main  n. Main pipe in a water-supply system.'),
(40019, 'w', '\r\nWaterman', ' n. 1 boatman plying for hire. 2 oarsman as regards skill in keeping the boat balanced.'),
(40020, 'w', '\r\nWatermark', ' â€”n. Faint design in some paper identifying the maker etc. â€”v. Mark with this.'),
(40021, 'w', '\r\nWater-meadow', ' n. Meadow periodically flooded by a stream.'),
(40022, 'w', '\r\nWater', 'melon  n. Large dark-green melon with red pulp and watery juice.'),
(40023, 'w', '\r\nWater-mill', ' n. Mill worked by a water-wheel.'),
(40024, 'w', '\r\nWater-pistol', ' n. Toy pistol shooting a jet of water.'),
(40025, 'w', '\r\nWater', 'polo  n. Game played by swimmers, with a ball like a football.'),
(40026, 'w', '\r\nWater-power', ' n. Mechanical force derived from the weight or motion of water.'),
