(40033, 'w', '\r\nWater-softener', ' n. Apparatus for softening hard water.'),
(40034, 'w', '\r\nWaterspout', ' n. Gyrating column of water and spray between sea and cloud.'),
(40035, 'w', '\r\nWater', 'table  n. = *water-level 2.'),
